                work->field_F06 = 4;
                work->field_2 = -1;
                work->field_7B3 = 0x12;
                work->field_F14 = 0x258;
                work->field_7B0 = 2;
                work->field_F04 = 0;
                D_actor_403200_80141C58 = 0x640;
                break;
        }
    }

    if (msg->h.id == 0x2804) {
        switch (msg->h.action) {
            case 0:
                work->field_0 = 0;
                break;

            case 1:
                work->field_7B3 = 0xA;
                work->field_7B0 = 2;
                work->field_7B6 = 0x7F;
                func_actor_403200_80133DD8(task);
